If $L$ is right dualizable 
\[\xymatrix@C=50pt{
{\ensuremath{ \hspace{1mm}\makebox[-1mm]{$\langle$}\makebox[0mm]{$\langle$}\hspace{1mm} {M_1\odot Q\odot N_1} \makebox[1mm]{$\rangle$}\makebox[0mm]{$\rangle$} }}\ar[r]^-{\mathrm{tr}(M_1\odot f\odot M_2)}\ar[d]_-{\mathrm{tr}\left( {\epsilon}^{({M_1},{N_1})}_{Q}\right)}
&{\ensuremath{ \hspace{1mm}\makebox[-1mm]{$\langle$}\makebox[0mm]{$\langle$}\hspace{1mm} {N_2\odot P\odot M_2} \makebox[1mm]{$\rangle$}\makebox[0mm]{$\rangle$} }}
\\
{\ensuremath{ \hspace{1mm}\makebox[-1mm]{$\langle$}\makebox[0mm]{$\langle$}\hspace{1mm} {Q} \makebox[1mm]{$\rangle$}\makebox[0mm]{$\rangle$} }}\ar[r]^-{\mathrm{tr}(f)}&{\ensuremath{ \hspace{1mm}\makebox[-1mm]{$\langle$}\makebox[0mm]{$\langle$}\hspace{1mm} {P} \makebox[1mm]{$\rangle$}\makebox[0mm]{$\rangle$} }}\ar[u]_{\mathrm{tr}\left( {\eta}^{({M_2},{N_2})}_{P}\right)}
}\]
commutes.

Suppose  $(M_1,N_1)$ is a dual pair, $(M_2,N_2)$ is a Morita equivalence, $Q$ and $P$ are 1-cells so that 
$M_1\odot Q\odot N_1$ and $N_2\odot P\odot M_2$ are defined.  For a right dualizable 1-cell
$L$ so that $M_1\odot L\odot M_2$ is defined, and a 2-cell $f\colon Q\odot L\to L\odot P$ the following diagram commutes.
\[\xymatrix@C=50pt{
 {\ensuremath{ \hspace{1mm}\makebox[-1mm]{$\langle$}\makebox[0mm]{$\langle$}\hspace{1mm} {M_1\odot Q\odot N_1} \makebox[1mm]{$\rangle$}\makebox[0mm]{$\rangle$} }}\ar[r]^-{\mathrm{tr}(M_1\odot f\odot M_2)}\ar[d]_-{\mathrm{tr}\left({\epsilon}^{({M_1},{N_1})}_{Q} \right)}
 &{\ensuremath{ \hspace{1mm}\makebox[-1mm]{$\langle$}\makebox[0mm]{$\langle$}\hspace{1mm} {N_2\odot P\odot M_2} \makebox[1mm]{$\rangle$}\makebox[0mm]{$\rangle$} }}\ar[d]^{\mathrm{tr}\left({\epsilon}^{({N_2},{M_2})}_{P}\right) }
 \\
 {\ensuremath{ \hspace{1mm}\makebox[-1mm]{$\langle$}\makebox[0mm]{$\langle$}\hspace{1mm} {Q} \makebox[1mm]{$\rangle$}\makebox[0mm]{$\rangle$} }}\ar[r]^-{\mathrm{tr}(f)}
 &{\ensuremath{ \hspace{1mm}\makebox[-1mm]{$\langle$}\makebox[0mm]{$\langle$}\hspace{1mm} {P} \makebox[1mm]{$\rangle$}\makebox[0mm]{$\rangle$} }}
}\]

[p:thesis][ps:indexed]
\begin{enumerate}
  \item If $f\colon A\to C$ is a monoid homomorphism, $(_fC,C_f)$ is a dual pair.
  \item If $F\colon \scr{A}\to \scr{C}$ be a $\scr{V}$-functor between $\scr{V}$-categories, $({_F\scr{C}},\scr{C}_F)$ is a dual pair.
\end{enumerate}

Let $F\colon \scr{A}\to \scr{C}$ be a $\scr{V}$-functor between $\scr{V}$-categories  and $\scr{Q}$ be a $(\scr{C},\scr{C})$-bimodule.  
Then the following two diagrams commute.
\[\xymatrix@C=12pt{
  \coprod_{a}\scr{A}(a,a)\ar[d]\ar[r]^-F&\coprod _{a}\scr{C}(F(a),F(a))\ar[r]
  &\coprod _c\scr{C}(c,c)\ar[d]
  \\ 
  {\ensuremath{ \hspace{1mm}\makebox[-1mm]{$\langle$}\makebox[0mm]{$\langle$}\hspace{1mm} {U_\scr{A}} \makebox[1mm]{$\rangle$}\makebox[0mm]{$\rangle$} }}\ar[rr]^{\chi_{({_F\scr{C}},\scr{C}_F)}(_F\scr{C})=\chi_{({_F\scr{C}},\scr{C}_F)}(\scr{C}_F)}
  && {\ensuremath{ \hspace{1mm}\makebox[-1mm]{$\langle$}\makebox[0mm]{$\langle$}\hspace{1mm} {U_\scr{C}} \makebox[1mm]{$\rangle$}\makebox[0mm]{$\rangle$} }}
 }
 \hspace{3em}
 \xymatrix{
  \coprod_{a} \scr{Q}(F(a),F(a))\ar[r]\ar[d]
  &\coprod_{c} \scr{Q}(c,c)\ar[d]
   \\
  {\ensuremath{ \hspace{1mm}\makebox[-1mm]{$\langle$}\makebox[0mm]{$\langle$}\hspace{1mm} {{_F\scr{Q}_F}} \makebox[1mm]{$\rangle$}\makebox[0mm]{$\rangle$} }}\ar[r]^-{\mathrm{tr}\left({\epsilon}^{F}_{\scr{Q}}\right)}
  &{\ensuremath{ \hspace{1mm}\makebox[-1mm]{$\langle$}\makebox[0mm]{$\langle$}\hspace{1mm} {\scr{Q}} \makebox[1mm]{$\rangle$}\makebox[0mm]{$\rangle$} }}
}\]

Let $\scr{C}$ and $\scr{D}$ be  categories enriched over $\scr{V}$, $c$ be an object of $\scr{C}$, $d$ be an object of $\scr{D}$,  $\scr{M}$ be a right dualizable $(\scr{C},\scr{D})$-bimodule, 
and suppose $E_d$ is a Morita equivalence.  
Let $\scr{Q}$ be a $(\scr{C},\scr{C})$-bimodule, $\scr{P}$ be a $(\scr{D},\scr{D})$-bimodule
and 
\[
  \phi\colon \scr{Q}\odot \scr{M}\to \scr{M}\odot \scr{P} 
\] 
be a natural transformation.  Then 
\begin{equation}
 \xymatrix@C=70pt{
  {\ensuremath{ \hspace{1mm}\makebox[-1mm]{$\langle$}\makebox[0mm]{$\langle$}\hspace{1mm} {_{E_c}\scr{Q}_{E_c}} \makebox[1mm]{$\rangle$}\makebox[0mm]{$\rangle$} }}\ar[d]^{\mathrm{tr}\left({\epsilon}^{E_c}_{\scr{Q}}\right)}\ar[r]^-{\mathrm{tr}({_{E_c}\scr{C}}\odot \phi\odot\scr{D}_{E_d})}
  &{\ensuremath{ \hspace{1mm}\makebox[-1mm]{$\langle$}\makebox[0mm]{$\langle$}\hspace{1mm} {_{E_d}\scr{P}_{E_d}} \makebox[1mm]{$\rangle$}\makebox[0mm]{$\rangle$} }}\ar[d]^{\mathrm{tr}\left({\epsilon}^{E_d}_{\scr{P}}\right)}
  \\
  {\ensuremath{ \hspace{1mm}\makebox[-1mm]{$\langle$}\makebox[0mm]{$\langle$}\hspace{1mm} {\scr{Q}} \makebox[1mm]{$\rangle$}\makebox[0mm]{$\rangle$} }}\ar[r]^-{\mathrm{tr}(\phi)}
  &{\ensuremath{ \hspace{1mm}\makebox[-1mm]{$\langle$}\makebox[0mm]{$\langle$}\hspace{1mm} {\scr{P}} \makebox[1mm]{$\rangle$}\makebox[0mm]{$\rangle$} }}}
\end{equation}
commutes.

Let $\scr{A}$ and $\scr{C}$ be  categories enriched over $\scr{V}$, $a$ be an object of $\scr{A}$, $c$ be an object of $\scr{C}$, and  $F\colon \scr{A}\to \scr{C}$ be a $\scr{V}$-functor. 
If  $E_c\colon \mathrm{End}_\scr{C}(c)\to \scr{C}$ is a Morita equivalence, 
\[\xymatrix@C=65pt{
 {\ensuremath{ \hspace{1mm}\makebox[-1mm]{$\langle$}\makebox[0mm]{$\langle$}\hspace{1mm} {\mathrm{End}_\scr{A}(a)} \makebox[1mm]{$\rangle$}\makebox[0mm]{$\rangle$} }}\ar[d]^{{\ensuremath{ \hspace{1mm}\makebox[-1mm]{$\langle$}\makebox[0mm]{$\langle$}\hspace{1mm} {E_a} \makebox[1mm]{$\rangle$}\makebox[0mm]{$\rangle$} }}}\ar[r]^-{\chi({_{F\circ E_a}\scr{C}_{E_c}})}
 &{\ensuremath{ \hspace{1mm}\makebox[-1mm]{$\langle$}\makebox[0mm]{$\langle$}\hspace{1mm} {\mathrm{End}_\scr{C}(c)} \makebox[1mm]{$\rangle$}\makebox[0mm]{$\rangle$} }}\ar[d]^{{\ensuremath{ \hspace{1mm}\makebox[-1mm]{$\langle$}\makebox[0mm]{$\langle$}\hspace{1mm} {E_c} \makebox[1mm]{$\rangle$}\makebox[0mm]{$\rangle$} }}}
 \\
 {\ensuremath{ \hspace{1mm}\makebox[-1mm]{$\langle$}\makebox[0mm]{$\langle$}\hspace{1mm} {\scr{A}} \makebox[1mm]{$\rangle$}\makebox[0mm]{$\rangle$} }}\ar[r]^-{{\ensuremath{ \hspace{1mm}\makebox[-1mm]{$\langle$}\makebox[0mm]{$\langle$}\hspace{1mm} {F} \makebox[1mm]{$\rangle$}\makebox[0mm]{$\rangle$} }}}&{\ensuremath{ \hspace{1mm}\makebox[-1mm]{$\langle$}\makebox[0mm]{$\langle$}\hspace{1mm} {\scr{C}} \makebox[1mm]{$\rangle$}\makebox[0mm]{$\rangle$} }}
}\]
commutes.

For $\scr{A}$, $\scr{C}$, $J$, $K$, $F$, $\phi$ and $\psi$ as above and objects $a$ of $\scr{A}$ and $c$ of $\scr{C}$, 
the following diagrams, where  vertical maps are induced by inclusions on hom sets, commute.
\[\xymatrix@C=60pt{
  {\ensuremath{ \hspace{1mm}\makebox[-1mm]{$\langle$}\makebox[0mm]{$\langle$}\hspace{1mm} {\scr{A}(a,J(a))} \makebox[1mm]{$\rangle$}\makebox[0mm]{$\rangle$} }} \ar[d] \ar[r]^-{\mathrm{tr}\left({_{E_a}\scr{A}}\odot \phi\odot \scr{C}_{E_{c}}\right)}
  &{\ensuremath{ \hspace{1mm}\makebox[-1mm]{$\langle$}\makebox[0mm]{$\langle$}\hspace{1mm} {\scr{C}(c,K(c))} \makebox[1mm]{$\rangle$}\makebox[0mm]{$\rangle$} }}\ar[d]
  \\
  {\ensuremath{ \hspace{1mm}\makebox[-1mm]{$\langle$}\makebox[0mm]{$\langle$}\hspace{1mm} {\scr{A}_J} \makebox[1mm]{$\rangle$}\makebox[0mm]{$\rangle$} }}\ar[r]^-{\mathrm{tr}(\phi)}
  &{\ensuremath{ \hspace{1mm}\makebox[-1mm]{$\langle$}\makebox[0mm]{$\langle$}\hspace{1mm} {\scr{C}_K} \makebox[1mm]{$\rangle$}\makebox[0mm]{$\rangle$} }}
  }
\hspace{10pt}

\xymatrix@C=5pt{
  {\ensuremath{ \hspace{1mm}\makebox[-1mm]{$\langle$}\makebox[0mm]{$\langle$}\hspace{1mm} {\scr{A}(a,J(a))} \makebox[1mm]{$\rangle$}\makebox[0mm]{$\rangle$} }} \ar[d] \ar[rr]^-{\mathrm{tr}\left({_{E_a}\scr{A}}\odot \phi\odot \scr{C}_{E_{c}}\right)}
  &&{\ensuremath{ \hspace{1mm}\makebox[-1mm]{$\langle$}\makebox[0mm]{$\langle$}\hspace{1mm} {\scr{C}(c,K(c))} \makebox[1mm]{$\rangle$}\makebox[0mm]{$\rangle$} }}\ar[d]
  \\
  {\ensuremath{ \hspace{1mm}\makebox[-1mm]{$\langle$}\makebox[0mm]{$\langle$}\hspace{1mm} {\scr{A}_J} \makebox[1mm]{$\rangle$}\makebox[0mm]{$\rangle$} }}\ar[r]^-{{\ensuremath{ \hspace{1mm}\makebox[-1mm]{$\langle$}\makebox[0mm]{$\langle$}\hspace{1mm} {\psi} \makebox[1mm]{$\rangle$}\makebox[0mm]{$\rangle$} }}}&{\ensuremath{ \hspace{1mm}\makebox[-1mm]{$\langle$}\makebox[0mm]{$\langle$}\hspace{1mm} {_F\scr{C}\odot \scr{C}_K\odot \scr{C}_F} \makebox[1mm]{$\rangle$}\makebox[0mm]{$\rangle$} }}\ar[r] 
  &{\ensuremath{ \hspace{1mm}\makebox[-1mm]{$\langle$}\makebox[0mm]{$\langle$}\hspace{1mm} {\scr{C}_K} \makebox[1mm]{$\rangle$}\makebox[0mm]{$\rangle$} }}
}\]
The remaining unlabeled map is induced by the map 
\[
  \coprod_{a\in \scr{A}}\scr{C}(F(a), K(F(a)))\to \coprod_{c\in \scr{C}}\scr{C}(c, K(c)).
\]

Suppose $f$, $j$, and $k$ are as above.   If $C_f$ is right dualizable then 
  the following diagram commutes. 
  \[
  \xymatrix@R=.5cm@C=1.5cm{
    \mathrm{THH}(C;C_k) \ar[r]^-{\mathrm{tr}(6.3)}  \ar[d]^\sim& \mathrm{THH}(A; A_j)\ar[d]^\sim\\
    \mathrm{THH}(\operatorname{Mod}^c_C;- \wedge C_k) \ar[r]^-{\mathrm{tr}(6.4)}  
  & \mathrm{THH}(\operatorname{Mod}^c_A ; -\wedge A_j).
    }
  \]

If $\scr{M}$ is a right dualizable $(\scr{C},\scr{D})$-bimodule  and $F\colon \scr{A}\to \scr{C}$ is an enriched functor, the trace of ${\epsilon}^{{F},{\scr{M}}}_{{{\scr{C}}}}$ is the composite 
\[{\ensuremath{ \hspace{1mm}\makebox[-1mm]{$\langle$}\makebox[0mm]{$\langle$}\hspace{1mm} {{_F\scr{C}_F}} \makebox[1mm]{$\rangle$}\makebox[0mm]{$\rangle$} }}\xrightarrow{\mathrm{tr}\left({\epsilon}^{F}_{U_\scr{C}}\right)}
{\ensuremath{ \hspace{1mm}\makebox[-1mm]{$\langle$}\makebox[0mm]{$\langle$}\hspace{1mm} {\scr{C}} \makebox[1mm]{$\rangle$}\makebox[0mm]{$\rangle$} }}\xrightarrow{\chi(\scr{M})} {\ensuremath{ \hspace{1mm}\makebox[-1mm]{$\langle$}\makebox[0mm]{$\langle$}\hspace{1mm} {\scr{D}} \makebox[1mm]{$\rangle$}\makebox[0mm]{$\rangle$} }}.\]
If $\alpha \colon \scr{Q}\to {_F\scr{C}_F}$ is a map of $(\scr{A},\scr{A})$-{\bf bimodules} 
 the trace of 
$\scr{Q}\odot {_F\scr{M}}\xrightarrow{\alpha \odot \mathrm{id}_{{_F\scr{M}}}}{_F\scr{C}_F}\odot {_F\scr{M}}\xrightarrow{{\epsilon}^{{F},{\scr{M}}}_{{{\scr{C}}}} } 
{_F\scr{M}}$
is 
\[{\ensuremath{ \hspace{1mm}\makebox[-1mm]{$\langle$}\makebox[0mm]{$\langle$}\hspace{1mm} {\scr{Q}} \makebox[1mm]{$\rangle$}\makebox[0mm]{$\rangle$} }}\xrightarrow{{\ensuremath{ \hspace{1mm}\makebox[-1mm]{$\langle$}\makebox[0mm]{$\langle$}\hspace{1mm} {\alpha} \makebox[1mm]{$\rangle$}\makebox[0mm]{$\rangle$} }}} {\ensuremath{ \hspace{1mm}\makebox[-1mm]{$\langle$}\makebox[0mm]{$\langle$}\hspace{1mm} { {_{F}\scr{C}_{F}}} \makebox[1mm]{$\rangle$}\makebox[0mm]{$\rangle$} }}\xrightarrow{\mathrm{tr}\left({\epsilon}^{F}_{U_\scr{C}}\right)}{\ensuremath{ \hspace{1mm}\makebox[-1mm]{$\langle$}\makebox[0mm]{$\langle$}\hspace{1mm} {\scr{C}} \makebox[1mm]{$\rangle$}\makebox[0mm]{$\rangle$} }}\xrightarrow{\chi(\scr{M})} {\ensuremath{ \hspace{1mm}\makebox[-1mm]{$\langle$}\makebox[0mm]{$\langle$}\hspace{1mm} {\scr{D}} \makebox[1mm]{$\rangle$}\makebox[0mm]{$\rangle$} }}. \]
